@layer theme, base, components, utilities;
@import 'tailwindcss/theme.css' layer(theme);
@import 'tailwindcss/preflight.css' layer(base);
@import 'tailwindcss/utilities.css';

@import '@spartan-ng/brain/hlm-tailwind-preset.css';
/* You can add global styles to this file, and also import other style files */

/* Semantic status colours sit beside spartan's tokens: they carry meaning
   (Active, Injured, MIA) and are deliberately not the accent. */
@theme inline {
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-info: var(--info);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-sidebar-muted: var(--sidebar-muted);
}

:root {
  color-scheme: light;

  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';

  --chart-1: #d8891a;
  --chart-2: #4f7cf0;
  --chart-3: #2fb574;
  --chart-4: #e4802b;
  --chart-5: #e5484d;
  --radius: 0.625rem;

  /* action / primary: amber. Dark text on amber, not the spec's white: white on
     #d8891a measures 2.79:1, under the 4.5:1 text floor. See check:contrast. */
  --primary: #d8891a;
  --primary-foreground: #241a05;
  --background: #f6f7fa;
  --foreground: #1b1e2b;
  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  /* accent is the subtle hover background, not the action colour */
  --accent: #e4e7ef;
  --accent-foreground: #1b1e2b;
  --destructive: #e5484d;
  --destructive-foreground: #0e1018;
  --border: #e4e7ef;
  --input: #e4e7ef;
  --ring: #b8730f; /* spec: amber at 35%, which measures 1.31:1; solid darker amber clears 3:1 */

  --success: #2fb574;
  --warning: #e4802b;
  --info: #4f7cf0;

  /* navigation rail: dark in both themes */
  --sidebar: #1e2233;
  --sidebar-foreground: #eceef6;
  --sidebar-muted: #9aa0b4;
  --sidebar-primary: #d8891a;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #2a2f45;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #2a2f45;
  --sidebar-ring: #d8891a;
}

:root.dark {
  color-scheme: dark;

  --chart-1: #f5b843;
  --chart-2: #6f97f6;
  --chart-3: #3ecb84;
  --chart-4: #f0983f;
  --chart-5: #f2585d;
  --primary: #f5b843;
  --primary-foreground: #241a05;
  --background: #0e1018;
  --foreground: #eceef6;
  --card: #171a26;
  --card-foreground: #eceef6;
  --popover: #171a26;
  --popover-foreground: #eceef6;
  --secondary: #1e2231;
  --secondary-foreground: #eceef6;
  --muted: #1e2231;
  --muted-foreground: #9aa0b4;
  --accent: #20263c;
  --accent-foreground: #eceef6;
  --destructive: #f2585d;
  --destructive-foreground: #0e1018;
  --border: #272b3b;
  --input: #272b3b;
  --ring: #f5b843;

  --success: #3ecb84;
  --warning: #f0983f;
  --info: #6f97f6;

  --sidebar: #10121c;
  --sidebar-foreground: #eceef6;
