4	/**
5	 * Read the FormFieldMeta off each field of a zod object schema. Keeps the label,
6	 * control kind, and placeholder on the schema (one source of truth) so a form
7	 * component reads them instead of restating them. Pair with `validateStandardSchema`
8	 * from `@angular/forms/signals` for validation, so shape, rules, and labels all
9	 * live on the one schema.
10	 */
11	export function formMeta(schema: z.ZodObject<z.ZodRawShape>): Record<string, FormFieldMeta> {
12	  const meta: Record<string, FormFieldMeta> = {};
13	  for (const [name, field] of Object.entries(schema.shape)) {
14	    meta[name] = (field as z.ZodType).meta() as unknown as FormFieldMeta;
15	  }
16	  return meta;
17	}
